using System.Text.RegularExpressions;
using Meziantou.Framework.Imaging.TestHarness;
using Xunit.Sdk;

namespace Meziantou.Framework.Imaging.Tests.Documentation;

/// <summary>
/// Keeps the published C# examples compiled: every C# block of the published Markdown files (the package readme.md
/// of src/Meziantou.Framework.Imaging and the pages of docs/Imaging) must be generated by Meziantou.FileReferencer from
/// a <c>#region</c> of the sample sources, which are compiled by the samples project and by this test project
/// (<see cref="DocumentationExampleTests"/> runs them). FileReferencer's <c>--check</c> (run by <c>eng/update-all.cs</c>)
/// verifies that the blocks are up to date. The pages of the documentation site also need a title, and their relative
/// links and images must exist.
/// </summary>
public sealed partial class DocumentationSnippetTests
{
    private const string EndMarker = "<!-- endref -->";
    private const string ReadmePath = "src/Meziantou.Framework.Imaging/readme.md";
    private const string DocumentationPath = "docs/Imaging";
    private const string FolderFileName = "_folder.yml";

    private static readonly FullPath Root = RepositoryPaths.Root;

    public static TheoryData<string> MarkdownFiles => [ReadmePath, .. GetDocumentationPages()];

    public static TheoryData<string> DocumentationPages => [.. GetDocumentationPages()];

    private static IEnumerable<string> GetDocumentationPages()
    {
        var directory = Root / DocumentationPath;
        if (!Directory.Exists(directory))
            return [];

        return Directory.EnumerateFiles(directory, "*.md", SearchOption.AllDirectories)
            .Where(path => !Path.GetFileName(path).Equals("AGENTS.md", StringComparison.Ordinal))
            .Select(path => FullPath.FromPath(path).MakePathRelativeTo(Root).Replace('\\', '/'))
            .Order(StringComparer.Ordinal);
    }

    [Fact]
    public void PublishedMarkdownFilesExist()
    {
        Assert.True(File.Exists(Root / ReadmePath), $"{ReadmePath} does not exist.");
        Assert.NotEmpty(GetDocumentationPages());
    }

    [Fact]
    public void DocumentationNamesHaveATwoDigitPrefix()
    {
        // Every page and group folder is named <nn>-<Name>; the images folders and their files are not pages
        var root = Root / DocumentationPath;
        var names = Directory.EnumerateFileSystemEntries(root, "*", SearchOption.AllDirectories)
            .Select(path => FullPath.FromPath(path).MakePathRelativeTo(root).Replace('\\', '/'))
            .Where(path => !path.Split('/').Contains("images", StringComparer.Ordinal))
            .Where(path => !path.EndsWith("AGENTS.md", StringComparison.Ordinal))
            .Where(path => !path.EndsWith(FolderFileName, StringComparison.Ordinal));
        var invalid = names.Where(path => !path.Split('/').All(segment => PrefixRegex().IsMatch(segment))).ToArray();

        // Name each page and folder '<nn>-<Name>', with a two-digit number
        Assert.Empty(invalid);
    }

    [Fact]
    public void DocumentationFoldersHaveATitle()
    {
        // The site shows the title of _folder.yml as the name of the folder; the images folders are not shown
        var root = Root / DocumentationPath;
        var folders = Directory.EnumerateDirectories(root, "*", SearchOption.AllDirectories)
            .Select(FullPath.FromPath)
            .Where(path => !path.MakePathRelativeTo(root).Replace('\\', '/').Split('/').Contains("images", StringComparer.Ordinal))
            .Prepend(root);
        var invalid = folders
            .Where(folder =>
            {
                var path = folder / FolderFileName;
                if (!File.Exists(path))
                    return true;

                var title = File.ReadAllLines(path).FirstOrDefault(line => line.StartsWith("title:", StringComparison.Ordinal));
                return title is null || string.IsNullOrWhiteSpace(title["title:".Length..]);
            })
            .Select(folder => folder.MakePathRelativeTo(Root).Replace('\\', '/'))
            .ToArray();

        // Each folder needs a _folder.yml file with a 'title'
        Assert.Empty(invalid);
    }

    [Theory]
    [MemberData(nameof(MarkdownFiles))]
    public void CSharpBlocksAreGeneratedFromSamples(string relativePath)
    {
        var lines = ReadLines(relativePath);
        var blocks = 0;
        for (var i = 0; i < lines.Length; i++)
        {
            var fence = lines[i].TrimStart();
            if (!fence.StartsWith("```", StringComparison.Ordinal))
                continue;

            var end = FindClosingFence(lines, i, relativePath);
            if (IsCSharp(fence[3..].Trim()))
            {
                if (i == 0 || !SampleReferenceRegex().IsMatch(lines[i - 1].Trim()))
                    throw new XunitException($"{relativePath}:{i + 1}: a C# block must be generated from a region of samples/Meziantou.Framework.Imaging.Samples: replace it with '<!-- ref:<relative path>/samples/Meziantou.Framework.Imaging.Samples/<File>.cs;region=<Region>;format=md-fenced-code-block;dedent=true -->' and '{EndMarker}', then run 'dotnet run ./eng/update-all.cs -- --step snippets'.");

                if (end + 1 >= lines.Length || lines[end + 1].Trim() != EndMarker)
                    throw new XunitException($"{relativePath}:{end + 1}: the generated C# block must be followed by '{EndMarker}'.");

                blocks++;
            }

            i = end;
        }

        // Some pages of the documentation site (an introduction, guidance) have no code
        if (relativePath == ReadmePath)
        {
            Assert.True(blocks > 0, $"{relativePath} has no C# block.");
        }
    }

    [Theory]
    [MemberData(nameof(DocumentationPages))]
    public void DocumentationPagesHaveATitle(string relativePath)
    {
        var lines = ReadLines(relativePath);
        if (lines.Length == 0 || lines[0] != "---")
            throw new XunitException($"{relativePath}:1: a page starts with a YAML front matter ('---').");

        var end = Array.IndexOf(lines, "---", 1);
        if (end < 0)
            throw new XunitException($"{relativePath}:1: the front matter is not closed by '---'.");

        var title = lines[1..end].FirstOrDefault(line => line.StartsWith("title:", StringComparison.Ordinal));
        if (title is null || string.IsNullOrWhiteSpace(title["title:".Length..]))
            throw new XunitException($"{relativePath}: the front matter has no 'title'.");

        // The site shows the title: the body starts its sections at '##'
        var inCode = false;
        for (var i = end + 1; i < lines.Length; i++)
        {
            if (lines[i].TrimStart().StartsWith("```", StringComparison.Ordinal))
            {
                inCode = !inCode;
            }
            else if (!inCode && lines[i].StartsWith("# ", StringComparison.Ordinal))
            {
                throw new XunitException($"{relativePath}:{i + 1}: the page repeats its title as a '#' heading; start the sections at '##'.");
            }
        }
    }

    [Theory]
    [MemberData(nameof(DocumentationPages))]
    public void DocumentationLinksExist(string relativePath)
    {
        var lines = ReadLines(relativePath);
        var directory = (Root / relativePath).Parent;
        var inCode = false;
        for (var i = 0; i < lines.Length; i++)
        {
            if (lines[i].TrimStart().StartsWith("```", StringComparison.Ordinal))
            {
                inCode = !inCode;
                continue;
            }

            if (inCode)
                continue;

            foreach (Match match in LinkRegex().Matches(lines[i]))
            {
                var target = match.Groups["target"].Value;
                // eng/update-all.cs checks that the cref links target a namespace of the public API
                if (target.StartsWith('#', StringComparison.Ordinal) || target.Contains("://", StringComparison.Ordinal) || target.StartsWith("mailto:", StringComparison.Ordinal) || target.StartsWith("cref:", StringComparison.Ordinal))
                    continue;

                var fragment = target.IndexOf('#', StringComparison.Ordinal);
                var path = fragment < 0 ? target : target[..fragment];
                if (!File.Exists(directory / path) && !Directory.Exists(directory / path))
                    throw new XunitException($"{relativePath}:{i + 1}: the link '{target}' does not point at a file of the repository.");
            }
        }
    }

    private static string[] ReadLines(string relativePath) => File.ReadAllText(Root / relativePath).ReplaceLineEndings("\n").Split('\n');

    private static bool IsCSharp(string language)
        => language.Equals("csharp", StringComparison.OrdinalIgnoreCase) || language.Equals("cs", StringComparison.OrdinalIgnoreCase) || language.Equals("c#", StringComparison.OrdinalIgnoreCase);

    private static int FindClosingFence(string[] lines, int start, string relativePath)
    {
        for (var i = start + 1; i < lines.Length; i++)
        {
            if (lines[i].Trim() == "```")
                return i;
        }

        throw new XunitException($"{relativePath}:{start + 1}: unterminated code block.");
    }

    [GeneratedRegex(@"^<!-- ref:(?:\.\./)+samples/Meziantou\.Framework\.Imaging\.Samples/[A-Za-z0-9]+\.cs;region=Imaging_[A-Za-z0-9]+;format=md-fenced-code-block;dedent=true -->$", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex SampleReferenceRegex();

    [GeneratedRegex(@"\]\((?<target>[^)\s]+)(?:\s+""[^""]*"")?\)", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex LinkRegex();

    [GeneratedRegex(@"^[0-9]{2}-[A-Z][A-Za-z0-9]*(?:\.md)?$", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex PrefixRegex();
}
